<section class="welcome-panel"><div><div class="eyebrow">YOUR DORM, YOUR PEOPLE</div><h2><?=dm_esc($title)?></h2><p><?=$admin?'Keep your residents comfortable and your day running smoothly. Everything you need, together in one place.':($staff?'See your assigned work, update your progress, and take care of the little things that make a home.':($super?'Support your dorm administrators and maintenance teams from one organized workspace.':'Stay on top of your bills, get a hand with repairs, and keep up with your dorm community.'))?></p><a href="<?=dm_url($super?'users':($admin?'residents':'announcements'))?>"><?=$super?'Meet your team':($admin?'Meet your community':'See what’s happening')?> <?=dm_icon('arrow')?></a></div><?=dm_building_art()?></section>
