 if($admin){$active=(int)dm_query("SELECT COUNT(*) FROM users WHERE dorm_id=? AND role='RESIDENT' AND status='active'",[$u['dorm_id']])->fetchColumn();$pending=(int)dm_query("SELECT COUNT(*) FROM users WHERE dorm_id=? AND role='RESIDENT' AND status='pending'",[$u['dorm_id']])->fetchColumn();$cap=(int)dm_query('SELECT COALESCE(SUM(capacity),0) FROM rooms WHERE dorm_id=? AND active=1',[$u['dorm_id']])->fetchColumn();$collected=array_sum(array_map(fn($b)=>$b['status']==='paid'&&substr($b['paid_at']??'',0,7)===date('Y-m')?dm_cents($b['paid_amount']??$b['total_amount']):0,$bills));dm_metric('Total residents',$active,"$pending awaiting approval",'users');dm_metric('Bed occupancy',$cap?round($active/$cap*100).'%':'0%',"$active of $cap beds occupied",'room','cyan');dm_metric('Collected this month',dm_money($collected/100),'Verified GCash and cash payments','wallet','green');dm_metric('Open requests',$open,'Repairs that need a little care','tool','purple');}
 elseif($staff){dm_metric('Assigned to me',count($reports),'Your maintenance workload','tool','cyan');dm_metric('Pending',count(array_filter($reports,fn($r)=>$r['status']==='PENDING')),'Ready to get started','clock');dm_metric('In progress',count(array_filter($reports,fn($r)=>$r['status']==='IN_PROGRESS')),'Work underway','tool','purple');dm_metric('Resolved',count($reports)-$open,'Thank you for your work','check','green');}
 else{$balance=array_sum(array_map(fn($b)=>$b['status']!=='paid'?dm_effective_cents($b):0,$bills));dm_metric('My room',$u['room_number']??'Unassigned',$u['dorm_name']??'Your dorm','room');dm_metric('Outstanding balance',dm_money($balance/100),count(array_filter($bills,fn($b)=>$b['status']!=='paid')).' unpaid bills','wallet','green');dm_metric('Open requests',$open,'We’re here to help','tool','cyan');dm_metric('Community updates',count($posts),'Keep up with your dorm','post','purple');}
 }
