 elseif($u['role']==='RESIDENT'){?><div class="panel-body"><a class="service-row" href="<?=dm_url('bills')?>"><span class="service-icon"><?=dm_icon('bill')?></span><div><strong>Track & pay bills</strong><p>View rent, utilities, and payment status.</p></div><?=dm_icon('arrow')?></a><a class="service-row" href="<?=dm_url('rooms')?>"><span class="service-icon"><?=dm_icon('room')?></span><div><strong>Browse rooms & availability</strong><p>Check room capacity, rent, and occupants.</p></div><?=dm_icon('arrow')?></a><a class="service-row" href="<?=dm_url('report_form')?>"><span class="service-icon"><?=dm_icon('tool')?></span><div><strong>Report a maintenance issue</strong><p>Tell us what needs fixing in your room.</p></div><?=dm_icon('arrow')?></a><a class="service-row" href="<?=dm_url('contact')?>"><span class="service-icon"><?=dm_icon('user')?></span><div><strong>Contact your administrator</strong><p>A hand when you need it.</p></div><?=dm_icon('arrow')?></a></div><?php }
 else{[$w,$a]=dm_report_scope($u);$rows=dm_all("SELECT m.*,u.name resident_name,r.room_number,s.name staff_name FROM maintenance_reports m JOIN users u ON u.id=m.resident_id JOIN rooms r ON r.id=m.room_id LEFT JOIN users s ON s.id=m.assigned_staff_id WHERE $w ORDER BY m.created_at DESC LIMIT 5",$a);dm_reports_table($rows);}
